def word_frequencies(words):
    frequency = {}
    for word in words:
        if word in frequency:
            frequency[word] += 1
        else:
            frequency[word] = 1
    return frequency

words = ['apple', 'banana', 'apple', 'orange', 'banana', 'apple']
result = word_frequencies(words)
