Translate the following Python code to a C# implementation that calculates the sum of all even numbers in a given list.
def sum_of_evens(numbers):
    return sum(x for x in numbers if x % 2 == 0)

public int SumOfEvens(List<int> numbers) {
    return numbers.Where(x => x % 2 == 0).Sum();
}

function fibonacci(n) {
    if (n <= 1) {
        return n;
    }
    return fibonacci(n - 1) + fibonacci(n - 2);
}

